const useDebounce = <T extends (...args: never[]) => unknown>(
  func: T,
  delay: number,
): ((...args: Parameters<T>) => void)

function letIfNotNull<T, R>(
  value: T | null | undefined,
  fn: (_: T) => R,
): R | undefined;

function deepMerge<T extends Record<string, unknown>>(
  base: T,
  override: DeepPartial<T>,
): T;

const useThrottle = <T extends (...args: never[]) => unknown>(
  func: T,
  interval?: number,
): ((this: unknown, ...args: Parameters<T>) => void)

function handleDateFormat(
  format: string,
  keyWords: string,
): { temp: string; p: Map<string, number> };

function useFollowSystemTheme(): {
  isDark: Ref<boolean>;
  toggle: () => void;
};

function useTimeDisplay(
  source?: Date | string | number,
  format?: string,
  options?: UseTimeDisplayOptions,
): {
  value: Ref<string>;
  start: () => void;
  stop: () => void;
};

const useDrag = (
  elementRef: HTMLElement,
  onMove?: () => void,
  interval?: number,
  threshold?: number,
): {
  destroy: () => void;
  isMove: () => boolean;
}

function useFormEvents<T>(emit: FormComponentEmits<T>): {
  handleInput: (value: T) => void;
  handleChange: (value: T) => void;
  handleFocus: () => void;
  handleBlur: () => void;
  handleClear: (clearValue: T) => void;
};

