/**
 * Base Element Styles
 * ------------------------------------------------------------------
 * body、pre、code、滚动条等基础元素样式。
 */

:root {
  font-size: 16px;
}

body {
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-family: var(--q-font-family-base);
  color: var(--q-color-text);
  background-color: var(--q-color-bg);
  /* 向后兼容 */
  color: var(--text-color);
  background-color: var(--background-color);
}

/* — pre / code 滚动条 — */
pre {
  width: 100%;
  overflow: scroll;
}

pre::-webkit-scrollbar,
code::-webkit-scrollbar {
  width: 4px;
  height: 4px;
  background-color: var(--q-color-bg);
}

pre::-webkit-scrollbar-thumb,
code::-webkit-scrollbar-thumb {
  background-color: var(--q-color-primary);
}

@media screen and (max-width: 768px) {
  pre::-webkit-scrollbar {
    width: 0;
    height: 0;
  }
}

/* — 自动填充覆盖 — */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
input:-webkit-autofill:active {
  -webkit-text-fill-color: var(--q-color-text);
  box-shadow: 0 0 0 1000px var(--q-color-bg-card) inset;
}

/* — Vue 过渡动画 — */
.fade-enter-active,
.fade-leave-active {
  transition: opacity var(--q-duration-normal) var(--q-easing-ease);
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}

/**
 * CSS Reset
 * ------------------------------------------------------------------
 * 统一盒模型、清除默认 margin/padding、继承颜色与背景。
 * 保持与旧版 `* {}` 重置行为一致，零破坏性迁移。
 */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  background-color: inherit;
  color: inherit;
}

/**
 * Component Styles — Badge
 * ------------------------------------------------------------------
 * 徽章样式类。
 */

.badge {
  display: inline-block;
  padding: var(--q-space-2) var(--q-space-4);
  font-size: var(--q-font-size-xs);
  font-weight: var(--q-font-weight-semibold);
  line-height: 1;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: var(--q-radius-sm);
}

/**
 * Component Styles — Button
 * ------------------------------------------------------------------
 * 通用按钮样式类（非 SFC 内联样式），供文档与布局复用。
 */

.button {
  background-color: var(--q-color-bg);
  color: var(--q-color-text);
  padding: var(--q-space-2) var(--q-space-3);
  border-radius: var(--q-radius-md);
  cursor: pointer;
  transition: var(--q-transition-background);
}

.button:hover {
  background-color: var(--q-color-bg-secondary);
}

.button-primary {
  padding: var(--q-space-3) var(--q-space-5);
  background-color: var(--q-color-button-bg);
  color: var(--q-color-button-text);
  cursor: pointer;
  border: 1px solid var(--q-color-white);
  border-radius: var(--q-radius-md);
  transition: var(--q-transition-background);
}

.button-primary:hover {
  background-color: var(--q-color-button-hover);
}

body.dark-mode .button-primary,
[data-theme='dark'] .button-primary {
  border: none;
}

.button-outline {
  background-color: transparent;
  color: var(--q-color-primary);
  border: 2px solid var(--q-color-primary);
  cursor: pointer;
  transition: var(--q-transition-color), var(--q-transition-background);
}

.button-outline:hover {
  background-color: var(--q-color-primary);
  color: var(--q-color-button-text);
}

/* — 悬停态 — */
.hover-primary {
  background-color: var(--q-color-bg);
  color: var(--q-color-text);
  transition: var(--q-transition-color), var(--q-transition-background);
}

.hover-primary:hover {
  background-color: var(--q-color-primary);
  color: var(--q-color-white);
}

.hover-red:hover {
  color: var(--q-color-red-400);
}

.bg-hover-secondary:hover {
  background-color: var(--q-color-bg-secondary);
}

/**
 * Component Styles — Card
 * ------------------------------------------------------------------
 * 卡片样式类与翻转动画。
 */

.card {
  transition: transform var(--q-duration-fast) var(--q-easing-ease-in-out);
}

.card-header {
  flex: 0 0 auto;
}

.card-body {
  flex: 1 1 auto;
}

.card-footer {
  flex: 0 0 auto;
}

.card-animation:hover {
  animation-name: q-up-down;
  animation-duration: var(--q-duration-slow);
  animation-timing-function: var(--q-easing-ease-in-out);
}

/**
 * Component Styles — FormTable
 * ------------------------------------------------------------------
 * 表格式表单组件样式类，包含表头、单元格、排序图标、分页等。
 */

.form-table-container {
  display: flex;
  flex-direction: column;
  gap: var(--q-space-4);
  width: 100%;
  height: 100%;
}

.form-table-container .label {
  font-weight: var(--q-font-weight-bold);
  margin: var(--q-space-2) 0;
}

/* — 选择框 — */
.empty-select {
  width: var(--q-space-6);
  height: var(--q-space-6);
  border: var(--q-space-1) solid var(--q-color-primary);
  transition: var(--q-transition-background);
  cursor: pointer;
}

.empty-select:hover {
  background-color: var(--q-color-primary);
}

.selected {
  background-color: var(--q-color-primary);
}

.empty-select.inverse {
  background-color: var(--q-color-white);
  border: var(--q-space-1) solid var(--q-color-white);
}

.empty-select.inverse:hover {
  background-color: var(--q-color-primary);
}

.empty-select.selected.inverse {
  background-color: var(--q-color-primary);
}

/* — 表格容器 — */
.input-table-container {
  display: flex;
  flex-direction: column;
  flex: 1;
  position: relative;
  width: 100%;
}

/* — 表格 — */
.form-table {
  border-collapse: collapse;
  table-layout: fixed;
}

.form-table th,
.form-table td {
  padding: var(--q-space-4) var(--q-space-5);
  text-align: left;
  border-bottom: 1px solid var(--q-color-gray-300);
}

.form-table-header-item {
  white-space: nowrap;
}

.form-table th {
  background-color: var(--q-color-primary);
  color: var(--q-color-white);
  border-right: 1px solid var(--q-color-white);
  border-bottom: none;
  font-weight: var(--q-font-weight-semibold);
  position: sticky;
  top: 0;
  z-index: var(--q-z-index-base);
}

.form-table th:last-child {
  border-right: none;
}

/* — 尺寸适配 — */
.table-small th,
.table-small td {
  padding: var(--q-space-2) var(--q-space-4);
}

.table-large th,
.table-large td {
  padding: var(--q-space-5) var(--q-space-6);
}

/* — 选中行样式 — */
.row-selected {
  background-color: rgba(91, 104, 216, 0.05);
}

.row-disabled {
  color: var(--q-color-gray-500);
}

/* — 无数据提示 — */
.table-empty {
  text-align: center;
  padding: var(--q-space-6);
  color: var(--q-color-gray-500);
  font-style: italic;
}

/* — 分页 — */
.form-table-pagination {
  width: 100%;
  margin-top: var(--q-space-4);
  display: flex;
  justify-content: flex-end;
}

/* — 排序图标 — */
.sort-icon {
  transform-origin: center center;
  position: absolute;
  right: var(--q-space-1);
  top: 50%;
}

/**
 * Component Styles — Input / Form Elements
 * ------------------------------------------------------------------
 * 文本输入、表单表格等通用样式类。
 */

.input-text-container {
  position: relative;
  flex: 1;
}

.text-input {
  flex: 1;
  padding: var(--q-space-2) var(--q-space-4);
  outline: none;
  border: 1px solid var(--q-color-gray-400);
  box-shadow: var(--q-shadow-xs);
  transition: var(--q-transition-border);
}

.text-input.uneditable {
  border: none;
  box-shadow: none;
}

.text-input:focus {
  border-color: var(--q-color-primary);
}

.text-input.error {
  border-color: var(--q-color-danger-border);
}

.text-hint {
  color: var(--q-color-danger-bg);
  font-size: var(--q-font-size-xs);
}

.text-input-icon {
  position: absolute;
  left: var(--q-space-2);
  top: 50%;
  transform: translateY(-50%);
}

.text-left-padding {
  padding-left: var(--q-space-8);
}

.input-text-container .close-icon {
  position: absolute;
  right: var(--q-space-4);
  bottom: 50%;
  transform: translateY(50%);
}

/* — 链接类 — */
.link-primary {
  color: var(--q-color-link);
  text-decoration: none;
  transition: var(--q-transition-color);
}

.link-primary:hover {
  color: var(--q-color-link-hover);
}

.link-gray {
  color: var(--q-color-gray-400);
  text-decoration: none;
}

.link-gray:hover {
  color: var(--q-color-gray-200);
}

/**
 * Component Styles — NavSection
 * ------------------------------------------------------------------
 * 导航区段样式类。
 */

.current-title {
  font-size: 1.1rem;
  font-weight: var(--q-font-weight-bold);
}

.back-button {
  display: flex;
  margin-bottom: var(--q-space-4);
  cursor: pointer;
  font-weight: var(--q-font-weight-bold);
}

.section-nav {
  list-style: none;
  padding-left: 0;
  margin: 0;
}

.nav-link {
  display: block;
  text-decoration: none;
  font-size: 0.95rem;
  padding: var(--q-space-3) var(--q-space-3);
  transition: var(--q-transition-all);
}

.nav-link.active {
  background-color: var(--q-color-primary);
  color: var(--q-color-white);
}

@media screen and (max-width: 768px) {
  .nav-section {
    width: 100%;
    max-width: 100vw;
  }
}

/**
 * Component Styles — Tag
 * ------------------------------------------------------------------
 * 标签样式类。
 */

.tag {
  font-size: var(--q-font-size-xs);
  padding: var(--q-space-2) var(--q-space-3);
  border-radius: var(--q-radius-md);
  font-weight: var(--q-font-weight-light);
  background-color: var(--q-color-tag);
  color: var(--q-color-white);
}

/**
 * Design System Entry Point
 * ==================================================================
 * qyani-components 企业级 CSS 设计系统入口。
 *
 * 加载顺序（CSS 层叠优先级从低到高）：
 *   1. Tokens   — 设计变量（颜色、阴影、间距、圆角、排版、动画）
 *   2. Theme    — 暗色主题覆盖
 *   3. Base     — 重置与基础元素样式
 *   4. Utilities— 工具类（布局、间距、颜色、排版、显示、响应式）
 *   5. Components— 组件级共享样式类
 *
 * 使用 @import 确保构建时正确合并到 dist/style.css。
 */

/* — 1. Tokens — */
@import './tokens/color.css';
@import './tokens/spacing.css';
@import './tokens/elevation.css';
@import './tokens/opacity.css';
@import './tokens/radius.css';
@import './tokens/typography.css';
@import './tokens/motion.css';

/* — 2. Theme — */
@import './theme/dark.css';

/* — 3. Base — */
@import './base/reset.css';
@import './base/base.css';

/* — 4. Utilities — */
@import './utilities/layout.css';
@import './utilities/spacing.css';
@import './utilities/color.css';
@import './utilities/typography.css';
@import './utilities/display.css';
@import './utilities/responsive.css';

/* — 5. Components — */
@import './components/button.css';
@import './components/badge.css';
@import './components/card.css';
@import './components/input.css';
@import './components/tag.css';
@import './components/form-table.css';
@import './components/nav-section.css';

/**
 * Markdown Body Styles
 * ------------------------------------------------------------------
 * Markdown 内容排版：适配组件库主题变量与明暗模式。
 * 由 MarkdownRender 组件通过 @import 引入。
 */

.markdown-body {
  -webkit-text-size-adjust: 100%;
  color: var(--q-color-text);
  font-family: var(--q-font-family-markdown);
  font-size: 14px;
  line-height: var(--q-line-height-relaxed);
  overflow-wrap: break-word;
  word-break: normal;
}

.markdown-body > :first-child {
  margin-top: 0;
}

.markdown-body > :last-child {
  margin-bottom: 0;
}

/* 标题层级清晰，并为锚点跳转保留安全滚动距离。 */
.markdown-body h1,
.markdown-body h2,
.markdown-body h3,
.markdown-body h4,
.markdown-body h5,
.markdown-body h6 {
  margin: 32px 0 16px;
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
  line-height: 1.35;
  scroll-margin-top: 24px;
}

.markdown-body h1 {
  padding-bottom: 12px;
  font-size: 28px;
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body h2 {
  padding-bottom: 8px;
  font-size: 22px;
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body h3 {
  font-size: 18px;
}

.markdown-body h4 {
  font-size: 16px;
}

.markdown-body h5 {
  font-size: 14px;
}

.markdown-body h6 {
  color: var(--q-color-text-muted);
  font-size: 13px;
}

.markdown-body p,
.markdown-body ul,
.markdown-body ol,
.markdown-body dl,
.markdown-body blockquote,
.markdown-body pre,
.markdown-body .markdown-table-wrapper,
.markdown-body figure {
  margin: 0 0 16px;
}

.markdown-body a {
  color: var(--q-color-link);
  font-weight: var(--q-font-weight-medium);
  text-decoration: underline;
  text-decoration-color: currentColor;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition:
    color 0.2s ease,
    text-decoration-color 0.2s ease;
}

.markdown-body a:hover {
  color: var(--q-color-link-hover);
  text-decoration-color: currentColor;
}

.markdown-body a:focus-visible {
  outline: 2px solid var(--q-color-primary);
  outline-offset: 2px;
  border-radius: 2px;
}

.markdown-body strong {
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
}

.markdown-body em {
  color: var(--q-color-text-description);
}

.markdown-body del {
  color: var(--q-color-text-muted);
}

.markdown-body hr {
  height: 1px;
  margin: 24px 0;
  border: 0;
  background-color: var(--q-color-border);
  opacity: var(--q-opacity-50);
}

/* 列表支持多层嵌套与任务项。 */
.markdown-body ul,
.markdown-body ol {
  padding-left: 24px;
}

.markdown-body li + li {
  margin-top: 6px;
}

.markdown-body li > p {
  margin: 8px 0;
}

.markdown-body li > ul,
.markdown-body li > ol {
  margin: 6px 0 0;
}

.markdown-body .task-list-item {
  list-style: none;
}

.markdown-body .task-list-item input[type='checkbox'] {
  width: 14px;
  height: 14px;
  margin: 0 8px 0 -20px;
  vertical-align: -2px;
}

/* 引用、代码和键盘按键采用克制的企业文档视觉。 */
.markdown-body blockquote {
  padding: 12px 16px;
  color: var(--q-color-text-description);
  background-color: var(--q-color-gray-100);
  border-left: 4px solid var(--q-color-primary);
  border-radius: 0 4px 4px 0;
}

.markdown-body blockquote > :last-child {
  margin-bottom: 0;
}

.markdown-body code,
.markdown-body kbd {
  padding: 2px 5px;
  color: var(--q-color-text);
  font-family: var(--q-font-family-mono);
  font-size: 0.875em;
  line-height: 1.5;
  background-color: var(--q-color-gray-100);
  border: 1px solid var(--q-color-border);
  border-radius: 4px;
}

.markdown-body kbd {
  font-size: 12px;
  font-weight: var(--q-font-weight-semibold);
  box-shadow: inset 0 -1px 0 var(--q-color-gray-300);
}

.markdown-body pre {
  max-width: 100%;
  padding: 16px;
  overflow: auto;
  color: #c9d1d9;
  line-height: 1.55;
  background-color: #0d1117;
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body pre code {
  display: block;
  min-width: max-content;
  padding: 0;
  color: inherit;
  font-size: 13px;
  background-color: transparent;
  border: 0;
  border-radius: 0;
}

/* 由渲染器注入容器：仅容器滚动，table 始终保留原生列宽计算。 */
.markdown-body .markdown-table-wrapper {
  width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body table {
  width: max-content;
  min-width: 100%;
  table-layout: auto;
  border-spacing: 0;
  border-collapse: separate;
}

.markdown-body th,
.markdown-body td {
  min-width: 112px;
  padding: 10px 12px;
  color: var(--q-color-text);
  text-align: left;
  vertical-align: middle;
  overflow-wrap: anywhere;
  border-right: 1px solid var(--q-color-border);
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body th {
  position: sticky;
  top: 0;
  z-index: 1;
  font-weight: var(--q-font-weight-semibold);
  white-space: nowrap;
  background-color: var(--q-color-gray-100);
}

.markdown-body tr:nth-child(even) td {
  background-color: var(--q-color-bg-secondary);
}

.markdown-body tr > :last-child {
  border-right: 0;
}

.markdown-body tr:last-child > * {
  border-bottom: 0;
}

.markdown-body .markdown-table-wrapper::-webkit-scrollbar {
  height: 6px;
}

.markdown-body .markdown-table-wrapper::-webkit-scrollbar-thumb {
  background-color: var(--q-color-gray-400);
  border-radius: var(--q-radius-full);
}

.markdown-body img {
  display: block;
  max-width: 100%;
  height: auto;
  margin: 16px auto;
  border-radius: 6px;
}

.markdown-body figure {
  text-align: center;
}

.markdown-body figcaption {
  margin-top: 8px;
  color: var(--q-color-text-muted);
  font-size: 13px;
}

.markdown-body details {
  padding: 12px 16px;
  background-color: var(--q-color-gray-100);
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body summary {
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
  cursor: pointer;
}

.markdown-body details[open] summary {
  margin-bottom: 12px;
}

@media screen and (max-width: 768px) {
  .markdown-body {
    font-size: 14px;
    line-height: 1.7;
  }

  .markdown-body h1 {
    font-size: 24px;
  }

  .markdown-body h2 {
    font-size: 20px;
  }

  .markdown-body h3 {
    font-size: 17px;
  }

  .markdown-body pre {
    padding: 12px;
    border-radius: 4px;
  }

  .markdown-body .markdown-table-wrapper {
    margin-right: -4px;
    border-radius: 4px;
  }

  .markdown-body table {
    font-size: 13px;
  }

  .markdown-body th,
  .markdown-body td {
    min-width: 96px;
    padding: 8px 10px;
  }
}

