/**
 * Spacing Design Tokens
 * ------------------------------------------------------------------
 * 基于 4px 基础单位的间距阶梯，共 12 档（0 → 48px）。
 *
 * 命名约定：--q-space-{n}     → 通用间距
 *           --q-space-{n}x    → 行列间距（gap）
 *
 * 向后兼容别名保留旧的 --distance / --half-distance 等。
 */

:root {
  /* — 间距阶梯 (4px base) — */
  --q-space-0: 0;
  --q-space-1: 0.125rem; /* 2px */
  --q-space-2: 0.25rem; /* 4px */
  --q-space-3: 0.375rem; /* 6px */
  --q-space-4: 0.5rem; /* 8px */
  --q-space-5: 0.75rem; /* 12px */
  --q-space-6: 1rem; /* 16px */
  --q-space-7: 1.25rem; /* 20px */
  --q-space-8: 1.5rem; /* 24px */
  --q-space-9: 2rem; /* 32px */
  --q-space-10: 2.5rem; /* 40px */
  --q-space-11: 3rem; /* 48px */
  --q-space-12: 4rem; /* 64px */

  /* — 向后兼容别名 — */
  --distance: var(--q-space-6);
  --half-distance: var(--q-space-4);
  --third-distance: var(--q-space-3);
  --fourth-distance: var(--q-space-2);
}

/**
 * Typography Design Tokens
 * ------------------------------------------------------------------
 * 字体族、字号、字重、行高与排版阶梯。
 *
 * 命名约定：--q-font-{property}-{value}
 */

:root {
  /* — 字体族 — */
  --q-font-family-base:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji';
  --q-font-family-mono:
    'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
  --q-font-family-markdown:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji';

  /* — 基础字号 — */
  --q-font-size-base: 1rem; /* 16px */
  --q-font-size-sm: 0.875rem; /* 14px */
  --q-font-size-xs: 0.75rem; /* 12px */
  --q-font-size-lg: 1.125rem; /* 18px */
  --q-font-size-xl: 1.25rem; /* 20px */
  --q-font-size-2xl: 1.5rem; /* 24px */
  --q-font-size-3xl: 2rem; /* 32px */

  /* — 文字阶梯（旧版 rem 简写） — */
  --q-font-size-03: 0.3rem;
  --q-font-size-05: 0.5rem;
  --q-font-size-08: 0.8rem;
  --q-font-size-085: 0.85rem;
  --q-font-size-12: 1.2rem;
  --q-font-size-15: 1.5rem;
  --q-font-size-2: 2rem;

  /* — 字重 — */
  --q-font-weight-light: 300;
  --q-font-weight-normal: 400;
  --q-font-weight-medium: 500;
  --q-font-weight-semibold: 600;
  --q-font-weight-bold: 700;

  /* — 行高 — */
  --q-line-height-tight: 1.2;
  --q-line-height-normal: 1.5;
  --q-line-height-relaxed: 1.75;

  /* — 字间距 — */
  --q-letter-spacing-normal: normal;
  --q-letter-spacing-wide: 0.025em;
  --q-letter-spacing-wider: 0.05em;
}

