  /** 下一页 */
  function next() {
    if (!props.loop && currentIndex.value >= totalItemsCount.value - 2) return;
    if (isAnimation) return;
    isAnimation = true;
    if (currentIndex.value >= totalItemsCount.value - 1) {
      useTransition.value = false;
      currentIndex.value = 1;
      requestAnimationFrame(() => {
        useTransition.value = true;
        setTimeout(next, 0);
      });
    } else {
      currentIndex.value += 1;
    }
    isAnimation = false;
  }

  /** 跳转到指定页 */
  function goTo(index: number) {
    currentIndex.value = index + 1;
  }

  /** 启动自动播放 */
  function startAutoplay() {
    if (props.autoplay && itemsCount.value > 1) {
      stopAutoplay();
      intervalId = setInterval(
        props.direction === 'next' ? next : prev,
        props.interval,
      );
    }
  }

  /** 停止自动播放 */
  function stopAutoplay() {
    if (intervalId) {
      clearInterval(intervalId);
      intervalId = null;
    }
  }

  /** 监听鼠标悬停停止播放 */
  function addHoverListeners() {
    const carouselEl = carousel.value;
    if (!carouselEl) return;
    carouselEl.addEventListener('mouseenter', stopAutoplay);
    carouselEl.addEventListener('mouseleave', startAutoplay);
  }

  onBeforeUnmount(() => {
    stopAutoplay();
    const carouselEl = carousel.value;
    if (carouselEl) {
      carouselEl.removeEventListener('mouseenter', stopAutoplay);
      carouselEl.removeEventListener('mouseleave', startAutoplay);
    }
  });

  onMounted(() => {
    startAutoplay();
    addHoverListeners();
  });

  watch(realIndex, (newVal) => emit('change', newVal));

  return {
    prev,
    next,
    goTo,
    items,
    itemsCount,
    totalItemsCount,
    currentIndex,
    realIndex,
    carousel,
    containerInner,
    transformStyle,
    transition,
    useTransition,
  };
}

