/**
 * 通用线段树（支持区间更新 + 区间查询）
 * 支持自定义合并函数、懒标记更新函数、默认值
 * 适用于：区间求和、最大值、最小值、区间加、区间覆盖等场景
 */
export class UseSegmentTree<T = number, Lazy = number> {
  private n: number; // 原始数据长度
  private merge: (a: T, b: T) => T; // 节点合并函数（如求和、最大值）
  private rootFunc: (
    left: number,
    right: number,
    lazyValue: Lazy,
    oldValue: T,
  ) => T; // 懒标记生效函数：决定 lazy 如何影响节点值
  private size: number; // 线段树底层满二叉树的“叶子层”大小（≥n 的最小 2 的幂）
  private defaultVal: T; // 查询无效区间时的返回值（单位元）

  private tree: T[]; // 线段树节点值数组（1-based，tree[1] 是根）
  private lazy: Lazy[]; // 懒标记数组（默认值为 0，表示无标记）

  /**
   * 初始化线段树
   *
   * @param data - 原始数据数组
   * @param rootFunc - 懒标记应用函数，签名：
   *                   (left: number, right: number, lazyValue: Lazy, oldValue: T) => T
   *                   用于计算：当区间 [left, right] 被赋予 lazyValue 时，节点应变成什么值
   *                   例如：
   *                     - 覆盖型：(l, r, v, _) => v
   *                     - 增量型（区间加）：(l, r, v, old) => old + v * (r - l + 1)
   * @param mergeFunc - 合并函数，签名：(a: T, b: T) => T，如求和、最大值、最小值
   * @param defaultVal - 查询无效区间时的返回值（单位元），如 0（sum）、-Infinity（max）、Infinity（min）
   */
  constructor(
    data: T[],
    rootFunc: (left: number, right: number, lazyValue: Lazy, oldValue: T) => T,
    mergeFunc: (a: T, b: T) => T = ((a: number, b: number) =>
      a + b) as unknown as (a: T, b: T) => T,
    defaultVal: T = 0 as T,
  ) {
    this.n = data.length;
    this.merge = mergeFunc;
    this.rootFunc = rootFunc;
    this.defaultVal = defaultVal;

    // 计算 size：扩展成满二叉树叶子数（≥n 的最小 2 的幂）
    this.size = 1;
    while (this.size < this.n) {
      this.size *= 2;
    }

    // 初始化线段树和懒标记数组（1-based，索引从 1 开始）
    this.tree = Array(2 * this.size).fill(this.defaultVal);
    this.lazy = Array(2 * this.size).fill(null); // 默认无懒标记

    // 叶子节点赋值：原始数据放在 [size, size + n - 1]
    for (let i = 0; i < this.n; i++) {
      this.tree[this.size + i] = data[i];
    }

    // 自底向上构建内部节点：从 size-1 到 1
    for (let i = this.size - 1; i >= 1; i--) {
      this.tree[i] = this.merge(this.tree[2 * i], this.tree[2 * i + 1]);
    }
  }

  /**
   * 对外接口：更新区间 [left, right]（闭区间，0-based）
   *
   * @param left - 更新区间左端点（0-based，原始数组索引）
   * @param right - 更新区间右端点
   * @param value - 要设置/增加的值
   */
  update(left: number, right: number, value: Lazy): void {
    // 根节点管理 [0, size-1]，递归更新
    this._update(1, 0, this.size - 1, left, right, value);
  }

  /**
   * 对外接口：查询区间 [left, right] 的合并值（闭区间，0-based）
   *
   * @param left - 查询区间左端点（0-based）
   * @param right - 查询区间右端点
   * @returns 合并结果（如区间和、最大值等）
   */
  query(left: number, right: number): T {
    return this._query(1, 0, this.size - 1, left, right);
  }

  /**
   * 懒标记下推函数（Lazy Propagation）
   * 将当前节点的 lazy 值推给子节点，并更新子节点的 tree 值
   *
   * @param root - 当前节点编号（1-based）
   * @param left - 当前节点管理的左边界（逻辑索引）
   * @param right - 当前节点管理的右边界（逻辑索引）
   */
  private _push(root: number, left: number, right: number): void {
    if (this.lazy[root] !== null) {
      // 有懒标记需要下推
      if (left !== right) {
        // 不是叶子节点 → 需要推给左右子树
        const mid = Math.floor((left + right) / 2);

        // 更新左子树的 lazy 和 tree 值
        this.lazy[root * 2] = this.lazy[root];
        this.tree[root * 2] = this.rootFunc(
          left,
          mid,
          this.lazy[root],
          this.tree[root * 2],
        );

        // 更新右子树的 lazy 和 tree 值
        this.lazy[root * 2 + 1] = this.lazy[root];
        this.tree[root * 2 + 1] = this.rootFunc(
          mid + 1,
          right,
          this.lazy[root],
          this.tree[root * 2 + 1],
        );
      }

      // 清空当前节点的 lazy 标记
      this.lazy[root] = null as Lazy;
    }
  }

  /**
   * 递归更新函数：将区间 [left, right] 的值设为 value（或按 rootFunc 计算）
   *
   * @param root - 当前节点编号
   * @param start - 当前节点管理的区间左端点
   * @param end - 当前节点管理的区间右端点
   * @param left - 待更新区间的左端点（用户输入）
   * @param right - 待更新区间的右端点（用户输入）
   * @param value - 要设置/增加的值
   */
  private _update(
    root: number,
    start: number,
    end: number,
    left: number,
    right: number,
    value: Lazy,
  ): void {
    // 区间无交集，直接返回
    if (end < left || right < start) {
      return;
    }

    // 当前节点区间完全被 [left, right] 覆盖
    if (left <= start && end <= right) {
      // 应用 lazy：更新当前节点值
      this.tree[root] = this.rootFunc(start, end, value, this.tree[root]);
      // 设置懒标记（子节点暂不更新）
      this.lazy[root] = value;
      return;
    }

    // 递归前先下推懒标记，确保子节点数据最新
    this._push(root, start, end);

    // 递归更新左右子树
    const mid = Math.floor((start + end) / 2);
    this._update(root * 2, start, mid, left, right, value);
    this._update(root * 2 + 1, mid + 1, end, left, right, value);

    // 回溯：用子节点更新当前节点
    this.tree[root] = this.merge(this.tree[root * 2], this.tree[root * 2 + 1]);
  }

  /**
   * 递归查询函数：查询区间 [queryLeft, queryRight] 的合并值
   *
   * @param node - 当前节点编号
   * @param left - 当前节点管理的左边界
   * @param right - 当前节点管理的右边界
   * @param queryLeft - 查询区间的左端点
   * @param queryRight - 查询区间的右端点
   * @returns 区间合并值
   */
  private _query(
    node: number,
    left: number,
    right: number,
    queryLeft: number,
    queryRight: number,
  ): T {
    // 无交集 → 返回单位元
    if (left > queryRight || right < queryLeft) {
      return this.defaultVal;
    }

    // 下推懒标记，确保当前节点值是最新的
    this._push(node, left, right);

    // 当前节点区间完全在查询区间内 → 直接返回
    if (left >= queryLeft && right <= queryRight) {
      return this.tree[node];
    }

    // 递归查询左右子树
    const mid = Math.floor((left + right) / 2);
    const leftRes = this._query(node * 2, left, mid, queryLeft, queryRight);
    const rightRes = this._query(
      node * 2 + 1,
      mid + 1,
      right,
      queryLeft,
      queryRight,
    );

    // 合并左右子树结果
    return this.merge(leftRes, rightRes);
  }
}

export default UseSegmentTree;

useSkipList.useSkipList.ts:
/**
 * 跳表层级结构接口
 * 每一层级包含指向下一个节点的指针和跨越的节点数
 * @template T 节点存储的数据类型
 */
interface SkipListLevel<T> {
  /** 指向同一层级下一个节点的指针 */
  forward: SkipListNode<T> | null;
  /** 跨越的节点数（相对于底层链表） */
  span: number; // 跨越的节点数（底层）
}

/**
 * 跳表节点类
 * 表示跳表中的一个节点，包含数据和多层级的连接信息
 * @template T 节点存储的数据类型
 */
class SkipListNode<T> {
  /** 节点存储的数据 */
  member: T;
  /** 指向前一个节点的指针（底层链表中的前驱节点） */
  backward: SkipListNode<T> | null;
  /** 节点在各层级上的连接信息数组 */
  levels: SkipListLevel<T>[];

  /**
   * 构造一个新的跳表节点
   * @param member 节点存储的数据
   * @param level 节点所处的最高层级数
   */
  constructor(member: T, level: number) {
    this.member = member;
    this.backward = null;
    this.levels = Array.from({ length: level }, () => ({
      forward: null,
      span: 0,
    }));
  }
}

/**
 * 跳表数据结构实现类
 * 跳表是一种基于概率的数据结构，可以在 O(log n) 时间复杂度内完成查找、插入和删除操作
 * 它通过维护一个多层级的链表结构来实现快速访问，是平衡树的一种替代方案
 * @template T 跳表中存储的数据类型
 */
export class UseSkipList<T> {
  /** 当前跳表的最大层级 */
  private _maxLevel: number = 1;
  /** 跳表头节点（哨兵节点，不存储实际数据） */
  private _header: SkipListNode<T>;
  /** 跳表尾节点指针 */
  private _tail: SkipListNode<T> | null = null;
  /** 跳表中元素的数量 */
  private _length: number = 0;
  /** 随机层级生成概率因子 */
  private _P: number;
  /** 跳表允许的最大层级 */
  private _MAX_LEVEL: number;
  /**
   * 比较函数，用于比较两个元素的大小关系
   * 返回负数表示 a < b，0 表示 a === b，正数表示 a > b
   */
  private _compare: (a: T, b: T) => number;

  /**
   * 构造一个新的跳表实例
   * @param P 随机层级生成概率因子，默认为 0.25
   * @param MAX_LEVEL 跳表最大层级，默认为 32
   * @param compare 自定义比较函数，若未提供则仅支持 number/string
   */
  constructor(P = 0.25, MAX_LEVEL = 32, compare?: (a: T, b: T) => number) {
    // 使用 null 作为哨兵 member，类型断言为 T（实际不会被访问）
    this._header = new SkipListNode<T>(null as unknown as T, MAX_LEVEL);
    this._P = P;
    this._MAX_LEVEL = MAX_LEVEL;
    // 初始化 header 的 span
    for (let i = 0; i < MAX_LEVEL; i++) {
      this._header.levels[i].span = 0;
    }
    if (compare) {
      this._compare = compare;
    } else {
      this._compare = (a, b) => {
        if (typeof a === 'number' && typeof b === 'number') {
          return a - b;
        } else if (typeof a === 'string' && typeof b === 'string') {
          return a.localeCompare(b);
        }
        throw new Error(
          'Default compare only supports number/string. Please provide custom compare function.',
        );
      };
    }
  }

  /**
   * 随机生成节点的层级数
   * 使用抛硬币方法，每次有 P 的概率升级到更高一层
   * @returns 生成的层级数
   */
  private _randomLevel(): number {
    let level = 1;
    while (Math.random() < this._P && level < this._MAX_LEVEL) {
      level++;
    }
    return level;
  }

  /**
   * 向跳表中插入一个新元素
   * @param member 要插入的元素
   * @returns 如果成功插入返回 true，如果元素已存在返回 false
   */
  insert(member: T): boolean {
    // update 数组记录每一层需要更新的节点（即新节点各层的前驱节点）
    const update: (SkipListNode<T> | null)[] = new Array(this._MAX_LEVEL).fill(
      this._header,
    );
    // rank 数组记录遍历过程中每一层已走过的节点数
    const rank: number[] = new Array(this._MAX_LEVEL).fill(0);

    // 从最高层开始向下查找插入位置
    let x: SkipListNode<T> | null = this._header;
    for (let i = this._maxLevel - 1; i >= 0; i--) {
      if (i === this._maxLevel - 1) {
        rank[i] = 0;
      } else {
        rank[i] = rank[i + 1];
      }
      // 在当前层向右查找，直到找到大于等于目标 member 的节点
      while (
        x.levels[i].forward &&
        this._compare(x.levels[i].forward!.member, member) < 0
      ) {
        rank[i] += x.levels[i].span;
        x = x.levels[i].forward!;
      }
      update[i] = x;
    }

    // 检查节点是否已经存在
    x = x.levels[0].forward;
    if (x && this._compare(x.member, member) === 0) {
      return false; // 已存在
    }

    // 随机生成新节点的层级
    const level = this._randomLevel();
    // 如果新节点的层级超过了当前跳表的最大层级，需要更新相关数据
    if (level > this._maxLevel) {
      for (let i = this._maxLevel; i < level; i++) {
        update[i] = this._header;
        rank[i] = 0;
        this._header.levels[i].span = this._length;
      }
      this._maxLevel = level;
    }

    // 创建新节点
    const newNode = new SkipListNode(member, level);

    // 更新各层级的连接关系
    for (let i = 0; i < level; i++) {
      const updateNode = update[i]!;
      newNode.levels[i].forward = updateNode.levels[i].forward;
      updateNode.levels[i].forward = newNode;

      // 更新跨度信息
      newNode.levels[i].span = updateNode.levels[i].span - (rank[0] - rank[i]);
      updateNode.levels[i].span = rank[0] - rank[i] + 1;
    }

    // 更新更高层级的跨度信息
    for (let i = level; i < this._maxLevel; i++) {
      update[i]!.levels[i].span += 1;
    }

    // 更新后继节点的 backward 指针
    if (newNode.levels[0].forward) {
      newNode.levels[0].forward.backward = newNode;
    } else {
      this._tail = newNode;
    }

    // 设置新节点的 backward 指针
    if (update[0] !== this._header) {
      newNode.backward = update[0]!;
    }

    this._length++;
    return true;
  }

  /**
   * 从跳表中删除指定元素
   * @param member 要删除的元素
   * @returns 如果成功删除返回 true，如果元素不存在返回 false
   */
  delete(member: T): boolean {
    // update 数组记录每一层需要更新的节点（即被删除节点各层的前驱节点）
    const update: (SkipListNode<T> | null)[] = new Array(this._MAX_LEVEL).fill(
      null,
    );
    let x: SkipListNode<T> | null = this._header;

    // 从最高层开始向下查找待删除节点
    for (let i = this._maxLevel - 1; i >= 0; i--) {
      // 在当前层向右查找，直到找到大于等于目标 member 的节点
      while (
        x.levels[i].forward &&
        this._compare(x.levels[i].forward!.member, member) < 0
      ) {
        x = x.levels[i].forward!;
      }
      update[i] = x;
    }

    // 找到待删除节点
    x = x.levels[0].forward;
    // 检查节点是否存在且匹配
    if (!x || this._compare(x.member, member) !== 0) {
      return false;
    }

    // 更新各层级的连接关系
    for (let i = 0; i < this._maxLevel; i++) {
      const up = update[i]!;
      if (up.levels[i].forward === x) {
        // 如果当前层的 forward 指向被删除节点，则更新连接关系
        up.levels[i].span += x.levels[i].span - 1;
        up.levels[i].forward = x.levels[i].forward;
      } else {
        // 否则只需减少跨度
        up.levels[i].span -= 1;
      }
    }

    // 更新后继节点的 backward 指针
    if (x.levels[0].forward) {
      x.levels[0].forward.backward = x.backward;
    } else if (x.backward) {
      this._tail = x.backward;
    } else {
      this._tail = null;
    }

    // 更新跳表最大层级
    while (
      this._maxLevel > 1 &&
      this._header.levels[this._maxLevel - 1].forward === null
    ) {
      this._maxLevel--;
    }

    this._length--;
    return true;
  }

  /**
   * 根据排名获取元素
   * @param rank 元素的排名（从 0 开始）
   * @returns 返回元素，如果排名无效则返回 null
   */
  get_by_rank(rank: number): T | null {
    // 检查排名有效性
    if (rank < 0 || rank >= this._length) return null;
    let traversed = 0;
    let x = this._header;
    // 从最高层开始向下查找
    for (let i = this._maxLevel - 1; i >= 0; i--) {
      // 在当前层向右移动，直到跨越目标排名
      while (x.levels[i].forward && traversed + x.levels[i].span <= rank + 1) {
        traversed += x.levels[i].span;
        x = x.levels[i].forward!;
      }
      // 如果正好到达目标节点则跳出循环
      if (traversed === rank + 1) break;
    }
    return x.member;
  }

  /**
   * 获取元素的排名
   * @param member 要查找的元素
   * @returns 元素的排名（从 0 开始），如果元素不存在则返回 null
   */
  get_rank(member: T): number | null {
    let rank = 0;
    let x: SkipListNode<T> | null = this._header;
    // 从最高层开始向下查找
    for (let i = this._maxLevel - 1; i >= 0; i--) {
      // 在当前层向右查找，直到找到大于等于目标 member 的节点
      while (
        x.levels[i].forward &&
        this._compare(x.levels[i].forward!.member, member) < 0
      ) {
        rank += x.levels[i].span;
        x = x.levels[i].forward!;
      }
    }
    x = x.levels[0].forward;
    // 检查节点是否存在且匹配
    if (x && this._compare(x.member, member) === 0) {
      return rank;
    }
    return null;
  }

  /**
   * 获取跳表中第一个元素
   * @returns 返回元素，如果跳表为空则返回 null
   */
  get_first(): T | null {
    if (this._length === 0) return null;
    const first = this._header.levels[0].forward;
    return first ? first.member : null;
  }

  /**
   * 获取跳表中最后一个元素
   * @returns 返回元素，如果跳表为空则返回 null
   */
  get_last(): T | null {
    return this._tail ? this._tail.member : null;
  }

  /**
   * 获取指定范围内的元素
   * @param start 起始位置（从 0 开始）
   * @param count 要获取的元素数量
   * @returns 包含元素的数组
   */
  range(start: number, count: number): T[] {
    // 参数校验
    if (count <= 0 || this._length === 0) return [];
    if (start < 0) start = 0;
    if (start >= this._length) return [];

    let traversed = 0;
    let x = this._header;
    // 从最高层开始向下定位起始位置
    for (let i = this._maxLevel - 1; i >= 0; i--) {
      while (x.levels[i].forward && traversed + x.levels[i].span <= start + 1) {
        traversed += x.levels[i].span;
        x = x.levels[i].forward!;
      }
    }

    // 从起始位置开始收集元素
    const result: T[] = [];
    let current: SkipListNode<T> | null = x;
    let fetched = 0;
    while (current && fetched < count) {
      result.push(current.member);
      current = current.levels[0].forward;
      fetched++;
    }
    return result;
  }

  /**
   * 获取指定范围内的元素（逆序）
   * @param start 起始位置（从 0 开始，从末尾计算）
   * @param count 要获取的元素数量
   * @returns 包含元素的数组
   */
  reverse_range(start: number, count: number): T[] {
    // 参数校验
    if (count <= 0 || this._length === 0) return [];
    if (start < 0) start = 0;
    if (start >= this._length) return [];

    // 计算正向排名
    const forwardRank = this._length - 1 - start;

    let traversed = 0;
    let x = this._header;
    // 从最高层开始向下定位起始位置
    for (let i = this._maxLevel - 1; i >= 0; i--) {
      while (
        x.levels[i].forward &&
        traversed + x.levels[i].span <= forwardRank + 1
      ) {
        traversed += x.levels[i].span;
        x = x.levels[i].forward!;
      }
    }

    // 从起始位置开始逆向收集元素
    const result: T[] = [];
    let current: SkipListNode<T> | null = x;
    let fetched = 0;
    while (current && fetched < count) {
      result.push(current.member);
      current = current.backward;
      fetched++;
    }
    return result;
  }

  /**
   * 获取跳表中元素的数量
   */
  get length(): number {
    return this._length;
  }
}

