// composables/useFollowSystemTheme.ts
import { nextTick, onMounted, onUnmounted, ref } from 'vue';

/**
 * 跟随系统主题变化，支持手动 toggle
 * 自动为 body 添加/移除 dark-mode 类
 * 手动切换后退出"跟随系统"模式
 *
 * 采用单例模式，所有调用方共享同一份主题状态
 */

/* ===== 模块级共享状态（单例） ===== */
const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
const isDark = ref(false);

let shouldFollowSystem = true;
let mountedCount = 0;

const updateTheme = (e?: MediaQueryListEvent) => {
  if (!shouldFollowSystem) return;
  const dark = e ? e.matches : mediaQuery.matches;
  isDark.value = dark;
  document.body.classList.toggle('dark-mode', dark);
};

const startListening = () => {
  mediaQuery.addEventListener('change', updateTheme);
};

const stopListening = () => {
  mediaQuery.removeEventListener('change', updateTheme);
};

/**
 * 手动切换主题
 * 一旦调用，将退出"跟随系统"模式
 */
const toggle = () => {
  if (shouldFollowSystem) {
    shouldFollowSystem = false;
    stopListening();
  }
  isDark.value = !isDark.value;
  document.body.classList.toggle('dark-mode', isDark.value);
  localStorage.setItem('preferred-theme', isDark.value ? 'dark' : 'light');
};

/* ===== 模块级初始化 ===== */
const saved = localStorage.getItem('preferred-theme');
if (saved) {
  shouldFollowSystem = false;
  isDark.value = saved === 'dark';
} else {
  isDark.value = mediaQuery.matches;
}

/* ===== Composable 入口 ===== */
export function useFollowSystemTheme() {
  onMounted(() => {
    mountedCount++;
    nextTick(() => {
      document.body.classList.toggle('dark-mode', isDark.value);
      if (shouldFollowSystem && mountedCount === 1) {
        startListening();
      }
    });
  });

  onUnmounted(() => {
    mountedCount--;
    if (mountedCount <= 0 && shouldFollowSystem) {
      stopListening();
    }
  });

  return {
    /** 当前是否为深色模式 */
    isDark,
    /** 手动切换主题 */
    toggle,
  };
}

useLRUCache.useLRUCache.ts:
/**
 * 存储数据的接口
 * @template T 存储值的类型
 */
interface StorageData<T> {
  [key: string]: T;
}

/*
 * 类型谓词，用于检查一个值是否为指定类型
 * @param value 要检查的值
 * @returns 是否为指定类型
 */
type TypeGuard<T> = (value: unknown) => value is T;

/**
 * LRU（最近最少使用）缓存实现类
 * 使用localStorage进行持久化存储，通过两个键分别存储数据和访问顺序
 * 当缓存超过最大容量时，自动淘汰最久未使用的数据
 * @template T 缓存值的类型
 */
export class UseLRUCache<T> {
  private readonly name: string; // 缓存名称，用于区分不同的缓存实例
  private readonly maxSize: number; // 缓存的最大容量
  private readonly storageKey: string; // 用于存储数据的localStorage键
  private readonly orderKey: string; // 用于存储访问顺序的localStorage键

  private data: StorageData<T>; // 存储缓存数据
  private order: string[]; // 存储键的访问顺序，按访问时间从早到晚排列
  private typeGuard: TypeGuard<T>;

  /**
   * 创建一个LRUCache实例
   * @param name 缓存名称，用于在localStorage中区分不同的缓存
   * @param typeGuard 类型谓词，用于检查数据是否为指定类型
   * @param maxSize 缓存的最大容量，默认10
   */
  constructor(name: string, typeGuard: TypeGuard<T>, maxSize = 8) {
    this.name = name;
    this.maxSize = Math.max(1, maxSize); // 确保容量至少为1

    // 生成localStorage中使用的键名
    this.storageKey = `__LRUCacheData__${this.name}`;
    this.orderKey = `__LRUCacheOrder__${this.name}`;

    // 从localStorage加载已有数据
    this.data = this.loadFromStorage<StorageData<T>>(this.storageKey) || {};
    this.order = this.loadFromStorage<string[]>(this.orderKey) || [];
    this.typeGuard = typeGuard;
    for (const value of Object.values(this.data)) {
      if (!this.typeGuard(value)) {
        this.clear();
        console.error(`LRUCache: ${this.name} 数据类型错误，已清除缓存`);
        break;
      }
    }
  }

  /**
   * 获取最近使用的一条记录的 key
   * @returns 最近使用的 key，如果没有则返回 null
   */
  getLatestKey(): string | null {
    const len = this.order.length;
    return len > 0 ? this.order[len - 1] : null;
  }

  /**
   * 获取最近使用的一条记录的 value
   * @returns 最近使用的 value，如果没有则返回 null
   */
  getLatestValue(): T | null {
    const key = this.getLatestKey();
    return key ? this.data[key] : null;
  }

  /**
   * 获取最近使用的前 N 条（倒序：最近的在前）
   * @param count 要获取的数量
   * @returns 数组，按“最近使用”排序（最新的在前）
   */
  getRecent(count: number = this.maxSize): Array<{ key: string; value: T }> {
    const recentKeys = this.order.slice(-count).reverse(); // 取最后 N 个，反转成“新→旧”
    return recentKeys.map((key) => ({
      key,
      value: this.data[key],
    }));
  }

  /**
   * 获取缓存值
   * @param key 要获取的键
   * @returns 对应的值，如果不存在则返回null
   */
  get(key: string): T | null {
    if (Object.hasOwn(this.data, key)) {
      // 更新访问顺序
      this.updateOrder(key);
      // 保存更新后的顺序到localStorage
      this.saveToStorage(this.orderKey, this.order);
      return this.data[key];
    }
    return null;
  }

  /**
   * 设置缓存值
   * @param key 要设置的键
   * @param value 要设置的值
   */
  set(key: string, value: T): void {
    // 存储值
    this.data[key] = value;
    // 更新访问顺序
    this.updateOrder(key);
    // 检查并执行淘汰策略
    this.evictIfFull();

    // 保存更新后的数据和顺序到localStorage
    this.saveToStorage(this.storageKey, this.data);
    this.saveToStorage(this.orderKey, this.order);
  }

  /**
   * 删除指定键的缓存
   * @param key 要删除的键
   */
  remove(key: string): void {
    if (Object.hasOwn(this.data, key)) {
      // 从数据中删除
      delete this.data[key];
      // 从顺序数组中删除
      this.order = this.order.filter((k) => k !== key);
      // 更新localStorage
      this.saveToStorage(this.storageKey, this.data);
      this.saveToStorage(this.orderKey, this.order);
    }
  }

  /**
   * 清空整个缓存
   */
  clear(): void {
    // 重置数据和顺序
    this.data = {};
    this.order = [];
    // 从localStorage中移除相关项
    localStorage.removeItem(this.storageKey);
    localStorage.removeItem(this.orderKey);
  }

  /**
   * 获取当前缓存中的项数
   * @returns 缓存中的项数
   */
  size(): number {
    return this.order.length;
  }

  /**
   * 获取缓存的最大容量
   * @returns 缓存的最大容量
   */
  capacity(): number {
    return this.maxSize;
  }

  /**
   * 获取缓存名称
   * @returns 缓存名称
   */
  getName(): string {
    return this.name;
  }

  /**
   * 获取当前所有键（按访问顺序：从最久到最近）
   * @returns 键的数组
   */
  keys(): string[] {
    // 返回顺序数组的副本，避免外部修改内部状态
    return [...this.order];
  }

  /**
   * 检查是否包含某个键
   * @param key 要检查的键
   * @returns 如果包含则返回true，否则返回false
   */
  has(key: string): boolean {
    return Object.hasOwn(this.data, key);
  }

  /**
   * 从localStorage加载数据
   * @param key 存储键名
   * @returns 解析后的数据，如果解析失败或不存在则返回null
   */
  private loadFromStorage<U>(key: string): U | null {
    try {
      const value = localStorage.getItem(key);
      return value ? JSON.parse(value) : null;
    } catch (e) {
      console.warn(
        `LRUCache "${this.name}": Failed to load from localStorage`,
        e,
      );
      return null;
    }
  }

  /**
   * 保存数据到localStorage
   * @param key 存储键名
   * @param value 要存储的值
   */
  private saveToStorage(key: string, value: unknown): void {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch (e) {
      console.error(
        `LRUCache "${this.name}": Failed to save to localStorage`,
        e,
      );
    }
  }

  /**
   * 更新访问顺序：将指定键移动到末尾（表示最近使用）
   * @param key 要更新的键
   */
  private updateOrder(key: string): void {
    // 从当前顺序中移除该键（如果存在）
    this.order = this.order.filter((k) => k !== key);
    // 将键添加到末尾（最近使用）
    this.order.push(key);
  }

  /**
   * 如果超出最大容量，淘汰最久未使用的项
   */
  private evictIfFull(): void {
    // 检查是否超出容量限制
    if (this.order.length > this.maxSize) {
      // 移除最久未使用的键（数组第一个元素）
      const oldestKey = this.order.shift()!;
      // 从数据中删除对应的项
      delete this.data[oldestKey];
      // 更新localStorage中的数据
      this.saveToStorage(this.storageKey, this.data);
    }
  }
}

useLocalStorage.useLocalStorage.ts:
interface StorageItem<T> {
  value: T;
  expires?: number; // 过期时间戳（毫秒）
}
export type TypeGuard<T> = (value: unknown) => value is T;
export class UseLocalStorage<T> {
  private readonly prefix: string;
  private readonly typeGuard: TypeGuard<T> | undefined;

  /*
   * @param prefix 存储键前缀
   * @param typeGuard 类型守卫函数，用于检查存储值是否符合预期类型
   */
  constructor(prefix: string = '', typeGuard?: TypeGuard<T>) {
    this.prefix = prefix;
    this.typeGuard = typeGuard;
  }

  /**
   * 设置存储项（支持过期时间）
   * @param key 存储键
   * @param value 存储值
   * @param expires 过期时间（毫秒），可选
   */
  setItem(key: string, value: T, expires?: number): void {
    try {
      if (this.typeGuard && !this.typeGuard(value)) {
        throw new Error('value is not a valid type');
      }
      const storageKey = this.getStorageKey(key);
      const item: StorageItem<T> = {
        value,
        expires: expires ? Date.now() + expires : undefined,
      };

      localStorage.setItem(storageKey, JSON.stringify(item));
    } catch (error) {
      console.error('LocalStorage setItem error:', error);
      throw error;
    }
  }

  /**
   * 获取存储项
   * @param key 存储键
   * @returns 存储值，如果不存在或已过期则返回 null
   */
  getItem(key: string): T | null {
    try {
      const storageKey = this.getStorageKey(key);
      const itemStr = localStorage.getItem(storageKey);

      if (itemStr === null) {
        return null;
      }

      const item: StorageItem<T> = JSON.parse(itemStr);
      // 基本结构校验（防御性编程）
      if (typeof item !== 'object' || item === null || !('value' in item)) {
        this.removeItem(key);
        return null;
      }
      // 检查是否过期
      if (item.expires && Date.now() > item.expires) {
        this.removeItem(key);
        return null;
      }
      // 类型守卫校验
      if (this.typeGuard && !this.typeGuard(item.value)) {
        console.warn(`Type guard failed for key: ${key}`);
        this.removeItem(key); // 可选：自动清理无效数据
        return null;
      }
      return item.value;
    } catch (error) {
      console.error('LocalStorage getItem error:', error);
      // 可选：清理损坏数据
      this.removeItem(key);
      return null;
    }
  }

  /**
   * 删除存储项
   * @param key 存储键
   */
  removeItem(key: string): void {
    try {
      const storageKey = this.getStorageKey(key);
      localStorage.removeItem(storageKey);
    } catch (error) {
      console.error('LocalStorage removeItem error:', error);
    }
  }

  /**
   * 清空所有存储项（带前缀的）
   */
  clear(): void {
    try {
      const keysToRemove: string[] = [];

      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith(this.prefix)) {
          keysToRemove.push(key);
        }
      }

      keysToRemove.forEach((key) => localStorage.removeItem(key));
    } catch (error) {
      console.error('LocalStorage clear error:', error);
    }
  }

  /**
   * 检查是否存在指定键
   * @param key 存储键
   * @returns 是否存在且未过期
   */
  hasItem(key: string): boolean {
    // 复用 getItem 逻辑更安全（包含类型和过期检查）
    return this.getItem(key) !== null;
  }

  /**
   * 获取所有键（带前缀的）
   * @returns 键数组
   */
  getKeys(): string[] {
    try {
      const keys: string[] = [];

      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith(this.prefix)) {
          // 移除前缀后返回原始键名
          keys.push(key.slice(this.prefix.length));
        }
      }

      return keys;
    } catch (error) {
      console.error('LocalStorage getKeys error:', error);
      return [];
    }
  }

  /**
   * 获取带前缀的实际存储键
   * @param key 原始键
   * @returns 带前缀的存储键
   */
  private getStorageKey(key: string): string {
    return `${this.prefix}${key}`;
  }
}

