import { useThrottle } from '@qianrenni/core';

/**
 * @param elementRef 目标元素的引用
 * @param onMove 移动事件的回调函数（可选）
 * @param interval 节流间隔（毫秒）
 * @param threshold 移动阈值（像素）
 * @returns 返回一个包含清理方法 `destroy` 的对象, 以及是否移动的标志 `isMove`
 */
export const useDrag = (
  elementRef: HTMLElement,
  onMove?: () => void,
  interval = 16,
  threshold = 10,
) => {
  interval = interval > 16 ? interval : 16;

  let isDragging = false;
  let startX = 0;
  let startY = 0;
  let startBottom = 0;
  let startRight = 0;
  let isMove = false;
  let downTarget: EventTarget | null = null; // 记录 pointerdown 时的实际目标

  const updatePosition = (e: PointerEvent) => {
    const dx = startX - e.clientX;
    const dy = startY - e.clientY;
    elementRef.style.bottom = `${startBottom + dy}px`;
    elementRef.style.right = `${startRight + dx}px`;
    onMove?.();
  };

  const throttleDrag = useThrottle(updatePosition, interval);

  const rawDrag = (e: PointerEvent) => {
    if (!isDragging) return;

    const dx = startX - e.clientX;
    const dy = startY - e.clientY;
    const distance = Math.hypot(dx, dy);

    if (!isMove && distance >= threshold) {
      isMove = true;
    }

    throttleDrag(e);
  };

  const startDrag = (e: PointerEvent) => {
    if (e.button !== 0 && e.pointerType === 'mouse') return;

    isDragging = true;
    isMove = false;

    startX = e.clientX;
    startY = e.clientY;

    const computedStyle = getComputedStyle(elementRef);
    startBottom = parseInt(computedStyle.bottom, 10) || 0;
    startRight = parseInt(computedStyle.right, 10) || 0;

    // 记录原始点击目标（可能是子元素）
    downTarget = e.target;

    elementRef.setPointerCapture(e.pointerId);
    document.body.style.userSelect = 'none';

    elementRef.addEventListener('pointermove', rawDrag);
  };

  const stopDrag = (e: PointerEvent) => {
    if (!isDragging) return;

    const didMove = isMove;
    isDragging = false;

    try {
      elementRef.releasePointerCapture(e.pointerId);
    } catch (err) {
      console.error('Failed to release pointer capture:', err);
    }

    elementRef.removeEventListener('pointermove', rawDrag);
    document.body.style.userSelect = '';

    // 如果没有拖动，尝试恢复原始点击行为
    if (!didMove && downTarget instanceof Element) {
      // 创建一个真实的 click 事件
      const clickEvent = new MouseEvent('click', {
        bubbles: true,
        cancelable: true,
        view: window,
        detail: 1,
        button: 0,
        clientX: e.clientX,
        clientY: e.clientY,
        screenX: e.screenX,
        screenY: e.screenY,
      });

      // 在原始目标上派发 click
      downTarget.dispatchEvent(clickEvent);
    }

    // 重置 downTarget
    downTarget = null;
  };

  elementRef.addEventListener('pointerdown', startDrag);
  elementRef.addEventListener('pointerup', stopDrag);
  elementRef.addEventListener('pointercancel', stopDrag);

  return {
    destroy: () => {
      elementRef.removeEventListener('pointerdown', startDrag);
      elementRef.removeEventListener('pointerup', stopDrag);
      elementRef.removeEventListener('pointercancel', stopDrag);
      if (isDragging) {
        elementRef.removeEventListener('pointermove', rawDrag);
        try {
          elementRef.releasePointerCapture(
            (elementRef as HTMLElement & { __activePointerId?: number })
              .__activePointerId || 0,
          );
        } catch (error) {
          console.error('Failed to release pointer capture:', error);
        }
      }
      document.body.style.userSelect = '';
    },
    isMove: () => isMove,
  };
};

useFormEvents.useFormEvents.ts:
// utils/useFormEvents.ts
import { FormComponentEmits } from '@/types';

/**
 * 为表单组件创建通用事件处理器
 * @param emit defineEmits 的返回函数
 * @returns 一组预绑定 emit 的事件处理函数
 */
export function useFormEvents<T>(emit: FormComponentEmits<T>) {
  return {
    /**
     * 处理 input 事件（值变化 + emit）
     */
    handleInput(value: T) {
      emit('update:modelValue', value);
      emit('input', value);
    },

    /**
     * 处理 change 事件
     */
    handleChange(value: T) {
      emit('update:modelValue', value);
      emit('change', value);
    },

    /**
     * 处理 focus
     */
    handleFocus() {
      emit('focus');
    },

    /**
     * 处理 blur
     */
    handleBlur() {
      emit('blur');
    },

    /**
     * 处理 clear
     */
    handleClear(clearValue: T) {
      emit('update:modelValue', clearValue as T);
      emit('clear');
    },
  };
}

useMousePosition.useMousePosition.ts:
// mouse.js
import { onMounted, onUnmounted, ref } from 'vue';

// 提升状态到模块作用域（单例模式）
const x = ref(0);
const y = ref(0);
let listenerCount = 0; // 引用计数器

// 统一的事件处理器
const update = (event: MouseEvent) => {
  x.value = event.pageX;
  y.value = event.pageY;
};

/**
 * 鼠标位置跟踪钩子
 * 功能：监听鼠标移动事件，返回实时坐标 {x, y}
 * 特性：自动管理事件监听（多个组件共用时仅绑定一次事件）
 */
export const useMousePosition = () => {
  // 每当组件挂载时
  onMounted(() => {
    if (listenerCount === 0) {
      window.addEventListener('mousemove', update);
    }
    listenerCount++; // 增加引用计数
  });

  // 每当组件卸载时
  onUnmounted(() => {
    listenerCount--;
    if (listenerCount === 0) {
      window.removeEventListener('mousemove', update);
    }
  });

  // 始终返回相同的引用
  return { x, y };
};

