 * ------------------------------------------------------------------
 * 标签样式类。
 */

.tag {
  font-size: var(--q-font-size-xs);
  padding: var(--q-space-2) var(--q-space-3);
  border-radius: var(--q-radius-md);
  font-weight: var(--q-font-weight-light);
  background-color: var(--q-color-tag);
  color: var(--q-color-white);
}

index.index.css:
/**
 * Design System Entry Point
 * ==================================================================
 * qyani-components 企业级 CSS 设计系统入口。
 *
 * 加载顺序（CSS 层叠优先级从低到高）：
 *   1. Tokens   — 设计变量（颜色、阴影、间距、圆角、排版、动画）
 *   2. Theme    — 暗色主题覆盖
 *   3. Base     — 重置与基础元素样式
 *   4. Utilities— 工具类（布局、间距、颜色、排版、显示、响应式）
 *   5. Components— 组件级共享样式类
 *
 * 使用 @import 确保构建时正确合并到 dist/style.css。
 */

/* — 1. Tokens — */
@import './tokens/color.css';
@import './tokens/spacing.css';
@import './tokens/elevation.css';
@import './tokens/opacity.css';
@import './tokens/radius.css';
@import './tokens/typography.css';
@import './tokens/motion.css';

/* — 2. Theme — */
@import './theme/dark.css';

/* — 3. Base — */
@import './base/reset.css';
@import './base/base.css';

/* — 4. Utilities — */
@import './utilities/layout.css';
@import './utilities/spacing.css';
@import './utilities/color.css';
@import './utilities/typography.css';
@import './utilities/display.css';
@import './utilities/responsive.css';

/* — 5. Components — */
@import './components/button.css';
@import './components/badge.css';
@import './components/card.css';
@import './components/input.css';
@import './components/tag.css';
@import './components/form-table.css';
@import './components/nav-section.css';

markdown.markdown.css:
/**
 * Markdown Body Styles
 * ------------------------------------------------------------------
 * Markdown 内容排版：适配组件库主题变量与明暗模式。
 * 由 MarkdownRender 组件通过 @import 引入。
 */

.markdown-body {
  -webkit-text-size-adjust: 100%;
  color: var(--q-color-text);
  font-family: var(--q-font-family-markdown);
  font-size: 14px;
  line-height: var(--q-line-height-relaxed);
  overflow-wrap: break-word;
  word-break: normal;
}

.markdown-body > :first-child {
  margin-top: 0;
}

.markdown-body > :last-child {
  margin-bottom: 0;
}

/* 标题层级清晰，并为锚点跳转保留安全滚动距离。 */
.markdown-body h1,
.markdown-body h2,
.markdown-body h3,
.markdown-body h4,
.markdown-body h5,
.markdown-body h6 {
  margin: 32px 0 16px;
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
  line-height: 1.35;
  scroll-margin-top: 24px;
}

.markdown-body h1 {
  padding-bottom: 12px;
  font-size: 28px;
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body h2 {
  padding-bottom: 8px;
  font-size: 22px;
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body h3 {
  font-size: 18px;
}

.markdown-body h4 {
  font-size: 16px;
}

.markdown-body h5 {
  font-size: 14px;
}

.markdown-body h6 {
  color: var(--q-color-text-muted);
  font-size: 13px;
}

.markdown-body p,
.markdown-body ul,
.markdown-body ol,
.markdown-body dl,
.markdown-body blockquote,
.markdown-body pre,
.markdown-body .markdown-table-wrapper,
.markdown-body figure {
  margin: 0 0 16px;
}

.markdown-body a {
  color: var(--q-color-link);
  font-weight: var(--q-font-weight-medium);
  text-decoration: underline;
  text-decoration-color: currentColor;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition:
    color 0.2s ease,
    text-decoration-color 0.2s ease;
}

.markdown-body a:hover {
  color: var(--q-color-link-hover);
  text-decoration-color: currentColor;
}

.markdown-body a:focus-visible {
  outline: 2px solid var(--q-color-primary);
  outline-offset: 2px;
  border-radius: 2px;
}

.markdown-body strong {
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
}

.markdown-body em {
  color: var(--q-color-text-description);
}

.markdown-body del {
  color: var(--q-color-text-muted);
}

.markdown-body hr {
  height: 1px;
  margin: 24px 0;
  border: 0;
  background-color: var(--q-color-border);
  opacity: var(--q-opacity-50);
}

/* 列表支持多层嵌套与任务项。 */
.markdown-body ul,
.markdown-body ol {
  padding-left: 24px;
}

.markdown-body li + li {
  margin-top: 6px;
}

.markdown-body li > p {
  margin: 8px 0;
}

.markdown-body li > ul,
.markdown-body li > ol {
  margin: 6px 0 0;
}

.markdown-body .task-list-item {
  list-style: none;
}

.markdown-body .task-list-item input[type='checkbox'] {
  width: 14px;
  height: 14px;
  margin: 0 8px 0 -20px;
  vertical-align: -2px;
}

/* 引用、代码和键盘按键采用克制的企业文档视觉。 */
.markdown-body blockquote {
  padding: 12px 16px;
  color: var(--q-color-text-description);
  background-color: var(--q-color-gray-100);
  border-left: 4px solid var(--q-color-primary);
  border-radius: 0 4px 4px 0;
}

.markdown-body blockquote > :last-child {
  margin-bottom: 0;
}

.markdown-body code,
.markdown-body kbd {
  padding: 2px 5px;
  color: var(--q-color-text);
  font-family: var(--q-font-family-mono);
  font-size: 0.875em;
  line-height: 1.5;
  background-color: var(--q-color-gray-100);
  border: 1px solid var(--q-color-border);
  border-radius: 4px;
}

.markdown-body kbd {
  font-size: 12px;
  font-weight: var(--q-font-weight-semibold);
  box-shadow: inset 0 -1px 0 var(--q-color-gray-300);
}

.markdown-body pre {
  max-width: 100%;
  padding: 16px;
  overflow: auto;
  color: #c9d1d9;
  line-height: 1.55;
  background-color: #0d1117;
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body pre code {
  display: block;
  min-width: max-content;
  padding: 0;
  color: inherit;
  font-size: 13px;
  background-color: transparent;
  border: 0;
  border-radius: 0;
}

/* 由渲染器注入容器：仅容器滚动，table 始终保留原生列宽计算。 */
.markdown-body .markdown-table-wrapper {
  width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body table {
  width: max-content;
  min-width: 100%;
  table-layout: auto;
  border-spacing: 0;
  border-collapse: separate;
}

.markdown-body th,
.markdown-body td {
  min-width: 112px;
  padding: 10px 12px;
  color: var(--q-color-text);
  text-align: left;
  vertical-align: middle;
  overflow-wrap: anywhere;
  border-right: 1px solid var(--q-color-border);
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body th {
  position: sticky;
  top: 0;
  z-index: 1;
  font-weight: var(--q-font-weight-semibold);
  white-space: nowrap;
  background-color: var(--q-color-gray-100);
}

.markdown-body tr:nth-child(even) td {
  background-color: var(--q-color-bg-secondary);
}

.markdown-body tr > :last-child {
  border-right: 0;
}

.markdown-body tr:last-child > * {
  border-bottom: 0;
}

.markdown-body .markdown-table-wrapper::-webkit-scrollbar {
  height: 6px;
}

.markdown-body .markdown-table-wrapper::-webkit-scrollbar-thumb {
  background-color: var(--q-color-gray-400);
  border-radius: var(--q-radius-full);
}

.markdown-body img {
  display: block;
  max-width: 100%;
  height: auto;
  margin: 16px auto;
  border-radius: 6px;
}

.markdown-body figure {
  text-align: center;
}

.markdown-body figcaption {
  margin-top: 8px;
  color: var(--q-color-text-muted);
  font-size: 13px;
}

.markdown-body details {
  padding: 12px 16px;
  background-color: var(--q-color-gray-100);
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body summary {
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
  cursor: pointer;
}

.markdown-body details[open] summary {
  margin-bottom: 12px;
}

@media screen and (max-width: 768px) {
  .markdown-body {
    font-size: 14px;
    line-height: 1.7;
  }

  .markdown-body h1 {
    font-size: 24px;
  }

  .markdown-body h2 {
    font-size: 20px;
  }

  .markdown-body h3 {
    font-size: 17px;
  }

  .markdown-body pre {
    padding: 12px;
    border-radius: 4px;
  }

  .markdown-body .markdown-table-wrapper {
    margin-right: -4px;
    border-radius: 4px;
  }

  .markdown-body table {
    font-size: 13px;
  }

  .markdown-body th,
  .markdown-body td {
    min-width: 96px;
    padding: 8px 10px;
  }
}

theme/dark.dark.css:
/**
 * Dark Theme Overrides
 * ------------------------------------------------------------------
 * 通过 `body.dark-mode` 或 `[data-theme="dark"]` 切换暗色主题。
 * 仅覆盖语义化 token，原始调色板不变。
 */

body.dark-mode,
[data-theme='dark'] {
  /* — 品牌主色：暗色背景上提亮，增强交互反馈 — */
  --q-color-primary: var(--q-color-yellow-300);
  --q-color-primary-hover: var(--q-color-yellow-400);
  --q-color-primary-active: var(--q-color-yellow-200);
  --q-color-primary-light: var(--q-color-yellow-100);
  --q-color-primary-lighter: var(--q-color-yellow-50);

  /* — 中性语义色 — */
  --q-color-text: #f0f0f0;
  --q-color-text-description: #b0b0b0;
  --q-color-text-muted: #999999;
  --q-color-text-secondary: #888888;
  --q-color-text-inverse: #ffffff;

  --q-color-bg: #121212;
  --q-color-bg-secondary: #3f3f3f;
  --q-color-bg-card: #232323;

  --q-color-border: #c5bebe;
  --q-color-border-light: #555555;

  --q-color-link: var(--q-color-yellow-400);
  --q-color-link-hover: var(--q-color-yellow-100);

  --q-color-tag: var(--q-color-yellow-100);

  /* — 按钮 — */
  --q-color-button-bg: var(--q-color-primary);
  --q-color-button-text: #ffffff;
  --q-color-button-hover: var(--q-color-primary-hover);
  --q-color-button-disabled: #555555;

  /* — 遮罩层 — */
  --q-color-overlay: rgba(255, 255, 255, 0.2);

  /* — 阴影色 — */
  --q-color-shadow: rgba(255, 255, 255, 0.5);
  --q-color-shadow-inverse: rgba(255, 255, 255, 0.9);

  /* — 灰阶反转 — */
  --q-color-gray-50: #202020;
  --q-color-gray-100: #202020;
  --q-color-gray-200: #2a2a2a;
  --q-color-gray-300: #333333;
  --q-color-gray-400: #444444;
  --q-color-gray-500: #555555;
  --q-color-gray-600: #666666;
  --q-color-gray-700: #888888;
  --q-color-gray-800: #aaaaaa;
  --q-color-gray-900: #cccccc;

  /* — 骨架屏渐变 — */
  --q-skeleton-gradient: linear-gradient(
    90deg,
    #202020 25%,
    #101010 50%,
    #202020 75%
  );

  /* ============================================================
   * 向后兼容别名（暗色模式覆盖）
   * ========================================================== */
  --color-inverse: var(--q-color-text-inverse);
  --background-color: var(--q-color-bg);
  --secondary-background-color: var(--q-color-bg-secondary);
  --text-color: var(--q-color-text);
  --text-description: var(--q-color-text-description);
  --text-color-secondary: var(--q-color-text-secondary);
  --subtle-text-color: var(--q-color-text-muted);
  --border-color: var(--q-color-border);
  --card-bg: var(--q-color-bg-card);
  --box-shadow: var(--q-color-shadow);

  --primary-color: var(--q-color-primary);
  --primary-hover: var(--q-color-primary-hover);
  --primary-light: var(--q-color-primary-light);
  --tag-primary-color: var(--q-color-tag);

  --link-color: var(--q-color-link);
  --link-hover: var(--q-color-link-hover);

  --button-bg: var(--q-color-button-bg);
  --button-text: var(--q-color-button-text);
  --button-hover: var(--q-color-button-hover);
  --button-disabled: var(--q-color-button-disabled);

  --bg-overlay: var(--q-color-overlay);
  --shadow-inverse: var(--q-color-shadow-inverse);

  --gray-100: var(--q-color-gray-100);
  --gray-200: var(--q-color-gray-200);
  --gray-300: var(--q-color-gray-300);
  --gray-400: var(--q-color-gray-400);
  --gray-500: var(--q-color-gray-500);
  --gray-600: var(--q-color-gray-600);
  --gray-700: var(--q-color-gray-700);

  --skeleton-linear-gradient: var(--q-skeleton-gradient);
}

tokens/color.color.css:
/**
 * Color Design Tokens
 * ------------------------------------------------------------------
 * 三层颜色架构：
 *   1. Palette  — 原始调色板（50–900），不随主题变化
 *   2. Semantic — 语义化颜色，映射 palette 到业务含义
 *   3. Alias    — 向后兼容别名，保持旧变量名可用
 *
 * 命名约定：--q-color-{role}-{shade}
 *           --q-color-{semantic-role}
 */

:root {
  /* ============================================================
   * 1. 原始调色板 (Palette)
   * ========================================================== */

  /* — 灰色 (Gray) — */
  --q-color-gray-50: #f8f9fa;
  --q-color-gray-100: #f1f1f1;
  --q-color-gray-200: #e9ecef;
  --q-color-gray-300: #dee2e6;
  --q-color-gray-400: #ced4da;
  --q-color-gray-500: #adb5bd;
  --q-color-gray-600: #868e96;
  --q-color-gray-700: #495057;
  --q-color-gray-800: #343a40;
  --q-color-gray-900: #212529;

  /* — 黄色 (Yellow / 品牌主色) — */
  --q-color-yellow-50: #fffbeb;
  --q-color-yellow-100: #fff5cc;
  --q-color-yellow-200: #ffe680;
  --q-color-yellow-300: #ffc300;
  --q-color-yellow-400: #ffd94d;
  --q-color-yellow-500: #dca000;
  --q-color-yellow-600: #b38600;
  --q-color-yellow-700: #806100;

  /* — 红色 (Red / Danger) — */
  --q-color-red-50: #fff0f1;
  --q-color-red-100: #ffcccc;
  --q-color-red-200: #f5a3a3;
  --q-color-red-300: #e74c4c;
  --q-color-red-400: #dc3545;
  --q-color-red-500: #c82333;
  --q-color-red-600: #a71d2a;
  --q-color-red-700: #871718;

  /* — 绿色 (Green / Success) — */
  --q-color-green-50: #e6f9f0;
  --q-color-green-100: #b2f2cc;
  --q-color-green-200: #7fe0a8;
  --q-color-green-300: #4cae5f;
  --q-color-green-400: #28a745;
  --q-color-green-500: #1e8438;
  --q-color-green-600: #176b2c;
  --q-color-green-700: #0f5221;

  /* — 蓝色 (Blue / Info) — */
  --q-color-blue-50: #e8f4fd;
  --q-color-blue-100: #c8e9e5;
  --q-color-blue-200: #8fcae8;
  --q-color-blue-300: #4aa3ed;
  --q-color-blue-400: #2189e0;
  --q-color-blue-500: #0d6efd;
  --q-color-blue-600: #0a58ca;
  --q-color-blue-700: #084298;

  /* — 橙色 (Orange / Warning) — */
  --q-color-orange-50: #fff8e1;
  --q-color-orange-100: #ffeac2;
  --q-color-orange-200: #ffd180;
  --q-color-orange-300: #ffc107;
  --q-color-orange-400: #ffa000;
  --q-color-orange-500: #e69500;
  --q-color-orange-600: #b37800;

  /* — 纯黑纯白 — */
  --q-color-white: #ffffff;
  --q-color-black: #000000;

  /* ============================================================
   * 2. 语义化颜色 (Semantic)
   * ========================================================== */

  /* — 品牌主色 — */
  --q-color-primary: var(--q-color-yellow-300);
  --q-color-primary-hover: var(--q-color-yellow-500);
  --q-color-primary-active: var(--q-color-yellow-600);
  --q-color-primary-light: var(--q-color-yellow-200);
  --q-color-primary-lighter: var(--q-color-yellow-50);

  /* — 功能色 — */
  --q-color-success: var(--q-color-green-400);
  --q-color-success-bg: var(--q-color-green-50);
  --q-color-success-border: var(--q-color-green-100);

  --q-color-warning: var(--q-color-white);
  --q-color-warning-bg: var(--q-color-orange-300);
  --q-color-warning-border: var(--q-color-orange-100);

  --q-color-danger: var(--q-color-white);
  --q-color-danger-bg: var(--q-color-red-400);
  --q-color-danger-border: var(--q-color-red-100);

  --q-color-info: var(--q-color-white);
  --q-color-info-bg: var(--q-color-blue-500);
  --q-color-info-border: var(--q-color-blue-100);

  /* — 中性语义色 — */
  --q-color-text: #333333;
  --q-color-text-description: #565656;
  --q-color-text-muted: #6c757d;
  --q-color-text-secondary: #868e96;
  --q-color-text-inverse: #111111;

  --q-color-bg: var(--q-color-gray-50);
  --q-color-bg-secondary: #e8e8e8;
  --q-color-bg-card: var(--q-color-white);

  --q-color-border: #686c71;
  --q-color-border-light: var(--q-color-gray-300);

  --q-color-link: #333333;
  --q-color-link-hover: var(--q-color-primary);

  /* — 标签/标记色 — */
  --q-color-tag: var(--q-color-yellow-100);

  /* — 按钮 — */
  --q-color-button-bg: var(--q-color-primary);
  --q-color-button-text: var(--q-color-white);
  --q-color-button-hover: var(--q-color-primary-hover);
  --q-color-button-disabled: var(--q-color-gray-200);

  /* — 遮罩层 — */
  --q-color-overlay: rgba(0, 0, 0, 0.5);

  /* — 阴影反色 — */
  --q-color-shadow-inverse: rgba(0, 0, 0, 0.9);

  /* ============================================================
   * 3. 向后兼容别名 (Legacy Aliases)
   *    保持旧变量名可用，内部引用新 token，零破坏性迁移。
   * ========================================================== */

  /* 纯色 */
  --color-white: var(--q-color-white);
  --color-black: var(--q-color-black);
  --color-inverse: var(--q-color-text-inverse);

  /* 背景 */
  --background-color: var(--q-color-bg);
  --secondary-background-color: var(--q-color-bg-secondary);
  --card-bg: var(--q-color-bg-card);

  /* 文字 */
  --text-color: var(--q-color-text);
  --text-description: var(--q-color-text-description);
  --text-color-secondary: var(--q-color-text-secondary);
  --subtle-text-color: var(--q-color-text-muted);

  /* 边框 */
  --border-color: var(--q-color-border);

  /* 阴影色 */
  --box-shadow: rgba(255, 255, 255, 0.5);
  --shadow-inverse: var(--q-color-shadow-inverse);

  /* 主色 */
  --primary-color: var(--q-color-primary);
  --primary-hover: var(--q-color-primary-hover);
  --primary-light: var(--q-color-primary-light);
  --tag-primary-color: var(--q-color-tag);

  /* 链接 */
  --link-color: var(--q-color-link);
  --link-hover: var(--q-color-link-hover);

  /* 功能色 */
  --success-color: var(--q-color-success);
  --success-bg: var(--q-color-success-bg);
  --success-border: var(--q-color-success-border);

  --warning-color: var(--q-color-warning);
  --warning-bg: var(--q-color-warning-bg);
  --warning-border: var(--q-color-warning-border);

  --danger-color: var(--q-color-danger);
  --danger-bg: var(--q-color-danger-bg);
  --danger-border: var(--q-color-danger-border);

  --info-color: var(--q-color-info);
  --info-bg: var(--q-color-info-bg);
  --info-border: var(--q-color-info-border);

  /* 灰阶 */
  --gray-100: var(--q-color-gray-100);
  --gray-200: var(--q-color-gray-200);
  --gray-300: var(--q-color-gray-300);
  --gray-400: var(--q-color-gray-400);
  --gray-500: var(--q-color-gray-500);
  --gray-600: var(--q-color-gray-600);
  --gray-700: var(--q-color-gray-700);

  /* 按钮 */
  --button-bg: var(--q-color-button-bg);
  --button-text: var(--q-color-button-text);
