}

.position-relative {
  position: relative;
}

.position-absolute {
  position: absolute;
}

.position-fixed {
  position: fixed;
}

.position-sticky {
  position: sticky;
}

/* ============================================================
 * Cursor
 * ========================================================== */

.mouse-cursor,
.cursor-pointer {
  cursor: pointer;
}

.mouse-cursor-disable,
.cursor-not-allowed {
  cursor: not-allowed;
}

/* ============================================================
 * Opacity
 * ========================================================== */

.opacity-0 {
  opacity: var(--q-opacity-0);
}
.opacity-10 {
  opacity: var(--q-opacity-10);
}
.opacity-20 {
  opacity: var(--q-opacity-20);
}
.opacity-30 {
  opacity: var(--q-opacity-30);
}
.opacity-40 {
  opacity: var(--q-opacity-40);
}
.opacity-50 {
