}

/* ============================================================
 * Border
 * ========================================================== */

.border-gray {
  border: 1px solid var(--q-color-border);
}

.border-vetical-gray {
  border-left: 1px solid var(--q-color-border);
  border-right: 1px solid var(--q-color-border);
