  border-radius: var(--q-space-3);
}

/* ============================================================
 * Shadow
 * ========================================================== */

.shadow-none {
  box-shadow: var(--q-shadow-none);
}

.shadow-xs {
  box-shadow: var(--q-shadow-xs);
}

.shadow-sm {
  box-shadow: var(--q-shadow-sm);
}

.shadow-md {
  box-shadow: var(--q-shadow-md);
}

.shadow-lg {
