  box-shadow: var(--q-shadow-xl);
}

/* — 向后兼容：旧版阴影类名 — */
.shadow-common {
  box-shadow: 0 0 10px var(--q-color-shadow);
}

/* ============================================================
 * Overflow
 * ========================================================== */

.overflow-hidden {
  overflow: hidden;
}

.overflow-auto {
  overflow: auto;
}

.overflow-scroll {
  overflow: scroll;
}

.overflow-visible {
  overflow: visible;
}

/* ============================================================
 * Misc
 * ========================================================== */

.active-common {
  color: var(--q-color-bg);
  background-color: var(--q-color-text-inverse);
}

.dot {
  position: absolute;
  top: 0;
  right: 0;
  transform: translateX(50%) translateY(-50%);
  min-width: var(--q-space-4);
  min-height: var(--q-space-4);
  border-radius: var(--q-radius-full);
  font-size: var(--q-font-size-xs);
  background-color: var(--q-color-info-bg);
}

.required::before {
  content: '*';
  color: red;
  margin-right: 2px;
  font-weight: bold;
}

/* — 动画工具类 — */
.animation-pulse {
  animation: q-pulse var(--q-duration-slow) var(--q-easing-linear) infinite;
}

.animation-rotate {
  animation: q-rotate 1s var(--q-easing-linear) infinite;
}

.animation-shimmer {
  animation: q-shimmer var(--q-duration-slow) var(--q-easing-linear) infinite;
}

